using Aspose.[identifier omitted];

// Load a 3D model from a file
Scene scene = new Scene();
scene.Open("input.obj", FileFormat.ObjFormat());

using Aspose.[identifier omitted];

// Load a 3D model into a Scene object
var scene = new Scene();
scene.Open("input.fbx", FbxFormat.FbxFormat());

// Access the root node and its first child entity
Node rootNode = scene.RootNode;
Node childNode = rootNode.ChildNodes()[0];

// Configure rendering options for image output
var renderOptions = new ImageRenderOptions();
renderOptions.BackgroundColor(Color.White);
renderOptions.EnableShadows(true);

// Render the scene to a PNG file
scene.Render(childNode, renderOptions, "output.png");

using Aspose.[identifier omitted];

// Load a COLLADA model
var scene = new Scene();
scene.Open("model.dae", ColladaFormat.ColladaFormat());

// Access the first visible node with an entity
Node targetNode = null;
foreach (Node node in scene.RootNode.ChildNodes())
{
    if (node.Visible() && node.Entity() != null)
    {
        targetNode = node;
        break;
    }
}

// Render with custom asset directories
var options = new ImageRenderOptions();
options.AssetDirectories.Add("./textures");
options.Name = "rendered_view";

scene.Render(targetNode, options, "rendered_view.png");

